'use strict';

// Real offline support for the Vessel Inspection PWA.
//
// Flutter no longer ships a caching service worker. The file it generates,
// `flutter_service_worker.js`, unregisters itself and caches nothing, so a
// stock `--pwa-strategy=offline-first` build still needs the network on every
// visit - which is how the app shipped until the client tested it at sea and
// reported it. The web build now uses `--pwa-strategy=none` and registers this
// file instead.
//
// `sw-manifest.js` is generated by .github/workflows/web.yml from the real
// contents of build/web, so the precache list cannot drift out of date as
// Flutter changes its output file names.

importScripts('sw-manifest.js');

const CACHE_NAME = 'vessel-inspection-' + (self.__CACHE_VERSION || 'dev');
const PRECACHE = self.__PRECACHE || [];
const SHELL = 'index.html';

// Installers served from downloads.html are tens of megabytes and are wanted
// once, not on every launch. Caching them would bloat the device for no gain.
const NEVER_CACHE = /\.(apk|ipa|exe|msi|zip)$/i;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    // cache.addAll() rejects the entire install if any single entry fails,
    // which would leave the app with no offline support at all. Add one at a
    // time so one missing file cannot take the whole thing down.
    let failed = 0;
    await Promise.all(PRECACHE.map(async (url) => {
      try {
        await cache.add(new Request(url, { cache: 'reload' }));
      } catch (e) {
        failed++;
      }
    }));
    if (failed > 0) {
      console.warn('sw: ' + failed + ' file(s) could not be precached');
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    // Drop caches from previous revisions so old app code cannot be served.
    const names = await caches.keys();
    await Promise.all(
      names
        .filter((n) => n.startsWith('vessel-inspection-') && n !== CACHE_NAME)
        .map((n) => caches.delete(n)),
    );
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;

  let url;
  try {
    url = new URL(request.url);
  } catch (e) {
    return;
  }
  // Never touch cross-origin requests.
  if (url.origin !== self.location.origin) return;
  // Let installer downloads stream straight from the network.
  if (NEVER_CACHE.test(url.pathname)) return;

  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);

    // Refreshing the page must work with no network. Prefer the exact page
    // that was asked for - otherwise downloads.html would come back as the app
    // shell when offline - and only fall back to the shell if it is not cached.
    if (request.mode === 'navigate') {
      try {
        return await fetch(request);
      } catch (e) {
        const page = await cache.match(request, { ignoreSearch: true });
        if (page) return page;
        const shell = await cache.match(SHELL);
        if (shell) return shell;
        return new Response(
          'This app has not finished downloading yet. Please connect to the '
          + 'internet once and open it again.',
          { status: 503, headers: { 'Content-Type': 'text/plain' } },
        );
      }
    }

    // Cache first: the app must start instantly and work with no network.
    const cached = await cache.match(request, { ignoreSearch: true });
    if (cached) {
      // Quietly refresh in the background so the next launch is up to date.
      event.waitUntil((async () => {
        try {
          const fresh = await fetch(request);
          if (fresh && fresh.ok && fresh.type === 'basic') {
            await cache.put(request, fresh.clone());
          }
        } catch (e) {
          // Offline: keep serving the cached copy.
        }
      })());
      return cached;
    }

    try {
      const fresh = await fetch(request);
      if (fresh && fresh.ok && fresh.type === 'basic') {
        cache.put(request, fresh.clone()).catch(() => {});
      }
      return fresh;
    } catch (e) {
      return new Response('', { status: 504 });
    }
  })());
});
